#include "app.h"
#include <hardware/adc.h>
#include <hardware/pwm.h>
#include <stdio.h>

// SHT31 0x44, LCD 0x27 and EEPROM 0x50 share GP4/GP5.
// GP26 selects a candidate threshold; GP14 saves it to EEPROM.
// GP15 green = healthy; GP16 red and GP17 blue show cooling demand.
volatile unsigned samples,errors,save_count;
volatile int temperature10,humidity10,threshold=28,candidate,demand,sensor_status,save_status;
static void number(char*s,unsigned v){s[0]='0'+v/10%10;s[1]='0'+v%10;}
int main(void){
 stdio_init_all();gpio_set_function(4,GPIO_FUNC_I2C);gpio_set_function(5,GPIO_FUNC_I2C);gpio_pull_up(4);gpio_pull_up(5);i2c_init(BUS,100000);
 gpio_init(14);gpio_pull_up(14);adc_init();adc_gpio_init(26);adc_select_input(0);
 for(unsigned p=15;p<=17;p++)gpio_set_function(p,GPIO_FUNC_PWM);
 pwm_config cfg=pwm_get_default_config();pwm_config_set_wrap(&cfg,999);pwm_config_set_clkdiv(&cfg,125.0f);pwm_init(pwm_gpio_to_slice_num(15),&cfg,true);pwm_init(pwm_gpio_to_slice_num(16),&cfg,true);
 int loaded=settings_load((int*)&threshold);puts(loaded==1?"BOOT settings restored":"BOOT default threshold 28C");
 int display=lcd_init();puts(display?"LCD missing":"LCD ready");
 bool last_button=false;unsigned last_edge=time_us_32();bool cooling=false;uint32_t next=time_us_32();
 while(1){
  candidate=15+(adc_read()*25u+2047u)/4095u;
  bool pressed=!gpio_get(14);unsigned now=time_us_32();
  if(pressed!=last_button&&(unsigned)(now-last_edge)>30000){last_edge=now;last_button=pressed;if(pressed){save_status=settings_save(candidate);if(!save_status){threshold=candidate;save_count++;puts("SAVE verified OK");}else{errors++;puts("SAVE verification failed");}}}
  if((int32_t)(now-next)<0){sleep_ms(2);continue;}next=now+500000;
  sensor_status=sensor_read((int*)&temperature10,(int*)&humidity10);samples++;
  if(sensor_status){errors++;demand=100;puts("FAULT SHT31; cooling fail-safe 100%");}
  else{if(temperature10>=threshold*10)cooling=true;else if(temperature10<=(threshold-1)*10)cooling=false;demand=cooling?20+(temperature10-threshold*10)*2:0;if(demand<20&&cooling)demand=20;if(demand>100)demand=100;}
  pwm_set_gpio_level(15,sensor_status?0:999);pwm_set_gpio_level(16,sensor_status?999:demand*10);pwm_set_gpio_level(17,demand*10);
  char top[]="T:00.0C H:00.0% ",bottom[]="SET:00 NEW:00   ";
  if(sensor_status)lcd_line(0,"SENSOR ERROR");else{unsigned t=temperature10<0?-temperature10:temperature10;number(top+2,t/10);top[5]='0'+t%10;number(top+10,humidity10/10);top[13]='0'+humidity10%10;lcd_line(0,top);}
  number(bottom+4,threshold);number(bottom+11,candidate);lcd_line(1,bottom);
  printf("SAMPLE %u T10=%d H10=%d SET=%d NEW=%d PWM=%d STATUS=%d\n",samples,temperature10,humidity10,threshold,candidate,demand,sensor_status);
 }
}

