#ifndef APP_H
#define APP_H
#include <pico/stdlib.h>
#include <hardware/i2c.h>
#define BUS i2c0
int bus_write(uint8_t,const uint8_t*,unsigned);
int bus_read(uint8_t,uint8_t*,unsigned);
int sensor_read(int*,int*);
int settings_load(int*);
int settings_save(int);
int lcd_init(void);
int lcd_line(unsigned,const char*);
#endif

#include "app.h"
int bus_write(uint8_t a,const uint8_t*b,unsigned n){return i2c_write_timeout_us(BUS,a,b,n,false,30000);}
int bus_read(uint8_t a,uint8_t*b,unsigned n){return i2c_read_timeout_us(BUS,a,b,n,false,30000);}

#include "app.h"
static uint8_t crc(const uint8_t*b){uint8_t c=255;for(int j=0;j<2;j++){c^=b[j];for(int k=0;k<8;k++)c=(c&128)?(c<<1)^0x31:c<<1;}return c;}
int sensor_read(int*t,int*h){uint8_t command[2]={0x24,0x00},b[6];if(bus_write(0x44,command,2)!=2)return -1;sleep_ms(16);if(bus_read(0x44,b,6)!=6)return -2;if(crc(b)!=b[2]||crc(b+3)!=b[5])return -3;unsigned rawt=(b[0]<<8)|b[1],rawh=(b[3]<<8)|b[4];*t=-450+(1750u*rawt+32767u)/65535u;*h=(1000u*rawh+32767u)/65535u;return 0;}
int settings_load(int*threshold){uint8_t pointer[2]={0,0},b[4];if(i2c_write_timeout_us(BUS,0x50,pointer,2,true,30000)!=2||bus_read(0x50,b,4)!=4)return -1;if(b[0]!=0x47||b[1]<15||b[1]>40||b[2]!=(uint8_t)~b[1]||b[3]!=0xa5)return 0;*threshold=b[1];return 1;}
int settings_save(int threshold){uint8_t b[6]={0,0,0x47,threshold,(uint8_t)~threshold,0xa5};if(bus_write(0x50,b,6)!=6)return -1;sleep_ms(6);int readback=0;if(settings_load(&readback)!=1||readback!=threshold)return -2;return 0;}

#include "app.h"
static int nibble(uint8_t n,bool data){uint8_t v=(n&0xf0)|8|(data?1:0),b[3]={v,(uint8_t)(v|4),v};return bus_write(0x27,b,3)==3?0:-1;}
static int byte(uint8_t v,bool data){if(nibble(v,data)||nibble(v<<4,data))return -1;sleep_us(50);return 0;}
int lcd_init(void){sleep_ms(40);if(nibble(0x30,0))return -1;sleep_ms(5);nibble(0x30,0);sleep_us(150);nibble(0x30,0);nibble(0x20,0);byte(0x28,0);byte(0x0c,0);byte(0x06,0);byte(0x01,0);sleep_ms(2);return 0;}
int lcd_line(unsigned row,const char*s){if(byte(row?0xc0:0x80,0))return -1;for(unsigned i=0;i<16;i++){char c=*s?*s++:' ';if(byte(c,1))return -1;}return 0;}
